async () => {
  try {
    const { execSync } = require('child_process');
    execSync('npx playwright install chrome', { stdio: 'inherit' });
    return 'Playwright Chrome installation completed';
  } catch (error) {
    return `Failed to install Playwright Chrome: ${error.message}`;
  }
}

async () => {
  try {
    const { execSync } = require('child_process');
    execSync('npx playwright install-deps', { stdio: 'inherit' });
    execSync('npx playwright install chromium', { stdio: 'inherit' });
    return 'Playwright dependencies and Chromium installation completed';
  } catch (error) {
    return `Failed to install Playwright dependencies: ${error.message}`;
  }
}

